<script lang="ts">
  import { app, isAdmin, isCashier, isApprover, canDecideLeave, leaveBalance, displayName, shiftLabel } from '#lib/state/app';
  import PageHeading from '#lib/components/PageHeading.svelte';
  import Icon from '#lib/components/Icon.svelte';
  import MetricCard from '#lib/components/MetricCard.svelte';
  import StatusPill from '#lib/components/StatusPill.svelte';
  import EmptyState from '#lib/components/EmptyState.svelte';
  import TeamReadiness from '#lib/components/TeamReadiness.svelte';
  import { dateLabel, timeLabel, todayJakarta, initials, leaveTypeLabel } from '#lib/components/format';
  const today = todayJakarta();
  const jakartaDate = (value: string) => new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Jakarta', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date(value));
  $: admin = isAdmin($app.user ?? undefined);
  $: cashier = isCashier($app.user ?? undefined);
  $: reviewer = isApprover($app.user);
  $: activeEmployees = $app.employees.filter((e) => e.status === 'active');
  $: todaysAttendance = $app.attendanceRecords.filter((r) => jakartaDate(r.clockIn) === today);
  $: pending = $app.leaveRequests.filter((r) => (r.status === 'pending' || r.adjustment?.status === 'pending') && (reviewer ? canDecideLeave(r) : r.employeeId === $app.user?.id));
  $: activeSession = $app.attendanceRecords.find((r) => r.employeeId === $app.user?.id && !r.clockOut);
  $: myLeave = $app.leaveRequests.filter((r) => r.employeeId === $app.user?.id);
  $: recentAttendance = (admin ? todaysAttendance : $app.attendanceRecords.filter((r) => r.employeeId === $app.user?.id)).slice().sort((a, b) => b.clockIn.localeCompare(a.clockIn)).slice(0, 4);
  $: bars = Array.from({ length: 7 }, (_, index) => { const date = new Date(`${today}T12:00:00+07:00`); date.setUTCDate(date.getUTCDate() - (6 - index)); const dateString = jakartaDate(date.toISOString()); return { date: dateString, label: new Intl.DateTimeFormat('id-ID', { weekday: 'short', timeZone: 'Asia/Jakarta' }).format(date), count: $app.attendanceRecords.filter((r) => jakartaDate(r.clockIn) === dateString).length }; });
  $: barMax = Math.max(1, ...bars.map((b) => b.count));
  const outletName = (id: string) => $app.outlets.find((o) => o.id === id)?.name || 'Outlet belum diatur';
</script>

<PageHeading eyebrow="RAJAKLANA · JABODETABEK" title={`Halo, ${$app.user?.fullName.split(' ')[0] || 'tim'} 👋`} description="Hari yang baik dimulai dengan tim yang terhubung."><div class="today"><Icon name="calendar" size={17}/>{dateLabel(today, true)}</div></PageHeading>

<section class="welcome"><div class="welcome-content"><span class="welcome-label">{admin ? 'RUANG KERJA HR' : 'RUANG KERJA ANDA'}</span><h2>{admin ? 'Tim terkelola.\nOperasional lebih tenang.' : activeSession ? 'Terima kasih sudah hadir.\nSemangat bekerja hari ini.' : 'Semua kebutuhan kerja,\ndalam satu tempat.'}</h2><p>{admin ? 'Pantau kehadiran kasir, tangani pengajuan, dan jaga informasi tim tetap rapi.' : 'Catat kehadiran, ajukan cuti atau izin, dan pantau pembaruan tanpa repot.'}</p><a class="welcome-link" href={admin ? '/employees' : cashier ? '/attendance' : '/leave'}>{admin ? 'Kelola tim' : cashier ? activeSession ? 'Lihat kehadiran Anda' : 'Mulai clock in' : 'Ajukan cuti atau izin'}<Icon name="arrow-right" size={17}/></a></div><div class="welcome-visual" aria-hidden="true"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><div class="visual-card visual-card-one"><span class="small-icon"><Icon name="check" size={16}/></span><div><strong>{admin ? `${activeEmployees.length} anggota tim` : 'Hari ini, lebih teratur'}</strong><small>Terhubung dalam satu ruang</small></div></div><div class="visual-card visual-card-two"><span class="small-icon"><Icon name="calendar" size={19}/></span><span>{admin ? `${pending.length} pengajuan untuk ditinjau` : `${$app.user ? leaveBalance($app.user.id) : 0} hari saldo cuti`}</span></div><div class="leaf leaf-one"></div><div class="leaf leaf-two"></div><div class="leaf leaf-three"></div></div></section>

<div class="metrics">{#if admin}<MetricCard label="Karyawan aktif" value={activeEmployees.length} detail={`${$app.outlets.filter((o) => o.active).length} outlet Jabodetabek`} icon="users"/><MetricCard label="Clock in hari ini" value={todaysAttendance.length} detail={`${todaysAttendance.filter((r) => !r.clockOut).length} kasir sedang bekerja`} icon="clock"/><MetricCard label="Perlu persetujuan" value={pending.length} detail="Termasuk perubahan dan pembatalan" icon="file" accent/><MetricCard label="Terlambat hari ini" value={todaysAttendance.filter((r) => r.lateMinutes > 0).length} detail="Berdasarkan shift pagi dan sore" icon="calendar"/>{:else}<MetricCard label="Saldo cuti" value={`${$app.user ? leaveBalance($app.user.id) : 0} hari`} detail="Tahun kalender berjalan" icon="calendar" accent/><MetricCard label="Pengajuan menunggu" value={myLeave.filter((r) => r.status === 'pending' || r.adjustment?.status === 'pending').length} detail="Pantau keputusan pada Cuti & izin" icon="file"/><MetricCard label={cashier ? 'Status kehadiran' : 'Penempatan utama'} value={cashier ? activeSession ? 'Bekerja' : 'Belum masuk' : $app.user ? outletName($app.user.outletId) : '—'} detail={activeSession ? `Masuk ${timeLabel(activeSession.clockIn)} · ${shiftLabel(activeSession.shift)}` : $app.user ? outletName($app.user.outletId) : ''} icon={cashier ? 'clock' : 'building'}/>{/if}</div>

{#if admin}<TeamReadiness employees={$app.employees} outlets={$app.outlets}/>{/if}

<div class="dashboard-grid"><section class="panel activity"><div class="section-heading"><h2>{reviewer ? 'Menunggu keputusan Anda' : 'Pengajuan terbaru Anda'}</h2><a href="/leave">Lihat semua<Icon name="chevron" size={14}/></a></div>{#if (reviewer ? pending : myLeave).length}<div class="activity-list">{#each (reviewer ? pending : myLeave.slice().sort((a, b) => b.createdAt.localeCompare(a.createdAt))).slice(0, 4) as request}<a href="/leave" class="activity-row"><span class="avatar">{initials(displayName(request.employeeId))}</span><div><strong>{reviewer ? displayName(request.employeeId) : leaveTypeLabel[request.type]}</strong><p>{reviewer ? `${leaveTypeLabel[request.type]} · ` : ''}{dateLabel(request.startDate)}</p>{#if request.adjustment?.status === 'pending'}<small>{request.adjustment.type === 'change' ? 'Perubahan tanggal' : 'Pembatalan cuti'}</small>{/if}</div><StatusPill label={request.adjustment?.status === 'pending' ? 'Perubahan' : request.status === 'pending' ? 'Menunggu' : request.status === 'approved' ? 'Disetujui' : request.status === 'rejected' ? 'Ditolak' : request.status === 'cancelled' ? 'Dibatalkan' : 'Perlu info'} tone={request.status === 'approved' && request.adjustment?.status !== 'pending' ? 'green' : request.status === 'rejected' ? 'red' : 'amber'}/></a>{/each}</div>{:else}<EmptyState icon="check" title={reviewer ? 'Semua sudah tertangani' : 'Belum ada pengajuan'} description={reviewer ? 'Pengajuan yang membutuhkan keputusan Anda akan muncul di sini.' : 'Cuti dan izin Anda akan muncul di sini setelah diajukan.'}/>{/if}</section>
  {#if admin}<section class="panel chart-panel"><div class="section-heading"><div><h2>Kehadiran kasir</h2><p>Catatan clock in · 7 hari terakhir</p></div><span class="chart-key"><span></span>Masuk</span></div><div class="chart" role="img" aria-label={`Clock in tujuh hari terakhir: ${bars.map((b) => `${b.label} ${b.count}`).join(', ')}`}><div class="chart-lines"><span></span><span></span><span></span></div>{#each bars as bar, index}<div class="bar-column"><span class="bar-value">{bar.count}</span><div class:current={index === 6} class="bar" style={`height:${Math.max(3, bar.count / barMax * 125)}px`}></div><span class="bar-label">{bar.label}</span></div>{/each}</div><div class="chart-foot"><span>{bars.reduce((total, b) => total + b.count, 0)} catatan masuk</span><a href="/reports">Buka rekap<Icon name="arrow-right" size={14}/></a></div></section>{:else}<section class="panel quick-panel"><div class="section-heading"><h2>Akses cepat</h2></div><a href="/leave"><span><Icon name="calendar"/></span><div><strong>Cuti & izin</strong><p>Ajukan kebutuhan Anda</p></div><Icon name="chevron" size={16}/></a>{#if cashier}<a href="/attendance"><span><Icon name="clock"/></span><div><strong>Masuk & pulang</strong><p>Catatan kehadiran Anda</p></div><Icon name="chevron" size={16}/></a>{/if}<a href="/profile"><span><Icon name="user"/></span><div><strong>Profil Anda</strong><p>Lengkapi kontak pribadi</p></div><Icon name="chevron" size={16}/></a></section>{/if}
</div>

<section class="panel attendance-preview"><div class="section-heading"><h2>{admin ? 'Kehadiran hari ini' : 'Kehadiran terbaru'}</h2><a href="/attendance">Lihat catatan<Icon name="chevron" size={14}/></a></div>{#if recentAttendance.length}<div class="attendance-rows">{#each recentAttendance as record}<a href="/attendance" class="attendance-row"><span class="avatar">{initials(displayName(record.employeeId))}</span><div class="attendance-person"><strong>{displayName(record.employeeId)}</strong><small>{outletName(record.outletId)} · {shiftLabel(record.shift)}</small></div><div class="attendance-time"><span>Masuk</span><strong>{timeLabel(record.clockIn)}</strong></div><div class="attendance-time"><span>Pulang</span><strong>{timeLabel(record.clockOut)}</strong></div><StatusPill label={!record.clockOut ? 'Sedang bekerja' : record.lateMinutes ? `Terlambat ${record.lateMinutes} mnt` : 'Selesai'} tone={!record.clockOut ? 'blue' : record.lateMinutes ? 'amber' : 'green'}/></a>{/each}</div>{:else}<div class="no-attendance"><Icon name="clock" size={21}/><span>Belum ada catatan kehadiran {admin ? 'hari ini' : 'Anda'}.</span>{#if cashier}<a href="/attendance">Buka absensi</a>{/if}</div>{/if}</section>

<style>
.today{display:flex;align-items:center;gap:.55rem;color:var(--muted);font-size:.76rem;background:#fffefa;border:1px solid var(--border);padding:.75rem 1rem;border-radius:10px}.welcome{position:relative;overflow:hidden;display:flex;align-items:center;justify-content:space-between;border-radius:22px;background:#f2ecd7;border:1px solid var(--border);padding:2.2rem 2.4rem;margin-bottom:1.5rem;min-height:245px}.welcome-content{max-width:530px;position:relative;z-index:2}.welcome-label{font-size:.61rem;letter-spacing:.15em;color:var(--muted);font-weight:600}.welcome h2{font-size:1.85rem;font-weight:600;letter-spacing:-.06em;line-height:1.2;white-space:pre-line;color:var(--muted);margin:.9rem 0}.welcome p{font-size:.81rem;color:var(--muted);line-height:1.8;max-width:380px;margin:0}.welcome-link{display:inline-flex;align-items:center;gap:.9rem;font-size:.77rem;font-weight:600;color:var(--muted);margin-top:1.3rem;text-decoration:none}.welcome-visual{position:absolute;width:320px;height:250px;right:3rem;bottom:0}.orbit{position:absolute;border:1px solid var(--border);border-radius:50%;width:245px;height:245px;right:-30px;top:50px}.orbit-two{width:170px;height:170px;right:7px;top:88px}.visual-card{position:absolute;display:flex;align-items:center;gap:.75rem;background:#fffef9df;border:1px solid var(--border);border-radius:13px;padding:1rem 1.1rem;box-shadow:0 8px 25px #9586540b;z-index:2}.visual-card-one{top:62px;left:12px;transform:rotate(-5deg)}.visual-card strong{font-size:.76rem;color:var(--muted);font-weight:600}.visual-card small{display:block;font-size:.59rem;margin-top:.4rem;color:var(--muted)}.small-icon{display:grid;place-items:center;width:34px;height:34px;background:#f4efdf;color:var(--muted);border-radius:10px}.visual-card-two{top:144px;right:-5px;transform:rotate(4deg);font-size:.72rem;color:var(--muted);padding:.85rem 1rem}.leaf{position:absolute;background:#e1d2a3;border-radius:100% 0 100% 0;width:72px;height:115px;bottom:-25px;right:80px;transform:rotate(-20deg)}.leaf-two{right:21px;bottom:-32px;transform:rotate(35deg);background:#e7dcb8}.leaf-three{right:115px;width:46px;height:85px;bottom:-25px;transform:rotate(-55deg);background:#cec29c}.metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:1rem;margin-bottom:1.5rem}.dashboard-grid{display:grid;grid-template-columns:1.15fr 1fr;gap:1.2rem;margin-bottom:1.2rem}.activity,.chart-panel,.quick-panel,.attendance-preview{padding:0;overflow:hidden}.section-heading{display:flex;align-items:center;justify-content:space-between;gap:1rem;padding:1.3rem 1.35rem;border-bottom:1px solid var(--border)}.section-heading h2{font-size:.89rem;font-weight:600;color:var(--muted);margin:0}.section-heading a{display:flex;align-items:center;gap:.4rem;font-size:.68rem;color:var(--muted);text-decoration:none;white-space:nowrap}.section-heading p{font-size:.66rem;margin:.5rem 0 0;color:var(--muted)}.activity-row{display:flex;align-items:center;gap:.8rem;text-decoration:none;padding:1.15rem 1.35rem;border-bottom:1px solid var(--border);color:var(--muted)}.activity-row:last-child{border-bottom:0}.avatar{display:grid;place-items:center;width:36px;height:36px;border-radius:10px;background:#f5f0e1;border:1px solid var(--border);color:var(--muted);font-size:.68rem;font-weight:600;flex-shrink:0}.activity-row>div{flex:1;min-width:0}.activity-row strong{font-size:.77rem;font-weight:600}.activity-row p{font-size:.65rem;color:var(--muted);margin:.4rem 0 0}.activity-row small{font-size:.61rem;color:var(--muted);margin-top:.4rem;display:block}.chart-key{font-size:.62rem;color:var(--muted);display:flex;align-items:center;gap:.4rem}.chart-key span{height:6px;width:6px;background:#bcaf86;border-radius:2px}.chart{height:225px;display:flex;align-items:flex-end;justify-content:space-around;gap:.4rem;position:relative;padding:1.8rem 1.35rem 1rem}.chart-lines{position:absolute;inset:2rem 1.3rem 2.5rem;display:flex;flex-direction:column;justify-content:space-between;pointer-events:none}.chart-lines span{border-top:1px dashed var(--border)}.bar-column{display:flex;flex-direction:column;align-items:center;justify-content:flex-end;gap:.55rem;position:relative;z-index:1;min-width:23px}.bar{width:25px;border-radius:5px 5px 2px 2px;background:#ede5c9}.bar.current{background:#afa06f}.bar-value{font-size:.59rem;color:var(--muted)}.bar-label{font-size:.59rem;color:var(--muted);min-width:30px;text-align:center}.chart-foot{display:flex;align-items:center;justify-content:space-between;border-top:1px solid var(--border);padding:.9rem 1.3rem;color:var(--muted);font-size:.66rem}.chart-foot a{display:flex;align-items:center;gap:.5rem;color:var(--muted);text-decoration:none}.quick-panel>a{display:flex;align-items:center;gap:.8rem;padding:1.2rem 1.35rem;border-bottom:1px solid var(--border);text-decoration:none;color:var(--muted)}.quick-panel>a>span{width:35px;height:35px;display:grid;place-items:center;background:#f7f3e6;border-radius:10px}.quick-panel>a>div{flex:1}.quick-panel strong{font-size:.8rem;color:var(--muted);font-weight:600}.quick-panel p{font-size:.65rem;color:var(--muted);margin:.4rem 0 0}.attendance-row{display:flex;align-items:center;gap:.85rem;padding:1rem 1.35rem;border-bottom:1px solid var(--border);text-decoration:none;color:var(--muted)}.attendance-row:last-child{border:0}.attendance-person{flex:1;min-width:0}.attendance-person strong{font-size:.78rem;font-weight:600}.attendance-person small{display:block;font-size:.64rem;color:var(--muted);margin-top:.35rem}.attendance-time{width:70px;display:flex;flex-direction:column;gap:.3rem}.attendance-time span{font-size:.6rem;color:var(--muted)}.attendance-time strong{font-size:.8rem;color:var(--muted);font-weight:500}.no-attendance{display:flex;align-items:center;justify-content:center;gap:.6rem;padding:2rem 1.3rem;font-size:.76rem;color:var(--muted)}.no-attendance a{color:var(--muted);font-size:.7rem}@media(max-width:1000px){.welcome-visual{right:.5rem;transform:scale(.85);transform-origin:right bottom}.welcome-content{max-width:350px}.metrics{gap:.75rem}.dashboard-grid{gap:1rem}.activity-row{padding:1rem}.section-heading{padding:1.1rem}}@media(max-width:800px){.welcome-visual{opacity:.55;right:-60px}.welcome-content{max-width:380px}.metrics{grid-template-columns:repeat(2,minmax(0,1fr))}.dashboard-grid{grid-template-columns:1fr}.chart{height:220px}.welcome{padding:1.7rem;min-height:245px}.welcome h2{font-size:1.65rem}}@media(max-width:600px){.today{font-size:.68rem;width:100%;justify-content:center}.welcome{padding:1.5rem;min-height:265px}.welcome-content{max-width:270px}.welcome h2{font-size:1.6rem}.welcome p{font-size:.75rem;max-width:245px}.welcome-visual{opacity:.25;right:-130px}.metrics{gap:.65rem}.metrics :global(.metric){padding:1.05rem}.metrics :global(strong){font-size:1.75rem}.section-heading h2{font-size:.8rem}.section-heading a{font-size:.62rem}.activity-row{padding:1rem}.activity-row strong{font-size:.74rem}.activity-row p{font-size:.62rem}.attendance-row{padding:1rem;gap:.6rem;flex-wrap:wrap}.attendance-person{min-width:140px}.attendance-time{width:45px}.attendance-row :global(.pill){font-size:.6rem;margin-left:auto}.no-attendance{flex-wrap:wrap;font-size:.71rem}}
  .today { background: var(--surface); color: var(--muted); border-color: var(--panel-border); border-radius: 13px; box-shadow: var(--raised-sm); }
  .welcome { background: var(--yellow-soft); border-color: var(--control-border); border-radius: 25px; box-shadow: var(--raised); }
  .welcome-label { color: #6f633e; font-weight: 700; }
  .welcome h2 { color: #4f472d; font-weight: 700; }
  .welcome p { color: #6f633e; }
  .welcome-link { color: #4b4328; min-height: 44px; }
  .visual-card { background: var(--surface); border-color: var(--panel-border); box-shadow: var(--raised-sm); border-radius: 16px; }
  .visual-card strong { color: var(--accent); }
  .small-icon { background: var(--surface); color: var(--accent); box-shadow: var(--inset); border-radius: 12px; }
  .section-heading, .activity-row, .quick-panel > a, .attendance-row, .chart-foot { border-color: var(--border); }
  .section-heading h2, .activity-row strong, .quick-panel strong, .attendance-person strong, .attendance-time strong { color: var(--ink); font-weight: 600; }
  .section-heading a, .chart-foot a, .no-attendance a { color: var(--accent); }
