  .activity-row:hover, .quick-panel > a:hover, .attendance-row:hover { background: #f1ead4; }
  .bar { background: #e4d7ad; box-shadow: inset 2px 2px 4px #c0b58f80, inset -2px -2px 4px #ffffff80; }
  .bar.current { background: var(--primary); }
  .chart-key span { background: var(--accent); }
  .chart-lines span { border-color: #eae1c1; }
</style>
